  {id:'leon',name:'Leon “L-Train” Carter',nick:'L-Train',tag:'THE MUSIC HEAD',floor:'upstairs',pos:[-5.2,-2.4],color:'#9b694f',shirt:'#4d79a2',pants:'#384460',hat:'#d26848',mood:'Quiet, focused on his music',line:'I’m putting together a beat in my head. Music helps me slow down when everything’s moving too fast.',rep:50,face:'◡',choices:[['What kind of sound are you going for? I’d love to hear.','Show genuine curiosity about his music.','+ CONNECTION','good',5],['Can you show me how you put a beat together?','Invite him to share something he loves.','+ ENCOURAGEMENT','good',4],['That’s just noise. Turn it off.','Dismiss his creative outlet.','− TRUST','bad',-6]]},
  {id:'nia',name:'Nia Williams',nick:'Nia',tag:'THE PLANNER',floor:'upstairs',pos:[4.8,-2.4],color:'#c88669',shirt:'#d57754',pants:'#416a62',hat:'#7d9dcb',mood:'Bright, always making a plan',line:'I’m writing down three little things I want to get done today. Nothing huge. Just things I can actually finish.',rep:50,face:'◡',choices:[['That’s a great idea. What’s one thing I could add?','Encourage her small, achievable goals.','+ SUPPORT','good',5],['Want to take a walk later? We can do it together.','Offer friendly accountability.','+ FRIENDSHIP','good',5],['Three things? You should be doing way more.','Make her feel like her effort is not enough.','− TRUST','bad',-7]]},
