 const label=document.createElement('canvas');label.width=512;label.height=96;const ctx=label.getContext('2d');ctx.fillStyle=isPlayer?'#c8ed76':'#19211de8';ctx.beginPath();ctx.roundRect(8,8,496,80,22);ctx.fill();ctx.strokeStyle=isPlayer?'#ecf5cc':'#dfd2b988';ctx.lineWidth=4;ctx.stroke();ctx.fillStyle=isPlayer?'#1e2b1c':'#f0ebdc';ctx.font='600 35px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(isPlayer?'JORDAN “J”':data.nick.toUpperCase(),256,48);const tex=new THREE.CanvasTexture(label);tex.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false}));sprite.scale.set(isPlayer?2.45:2.1,.4,1);sprite.position.y=2.27;g.add(sprite);g.userData.person=data;g.userData.label=sprite;return g;}
function addStairs(){const x=7.15,z=1.5;for(let i=0;i<5;i++)box(world,x-i*.16,.08+i*.1,z+i*.34,.85,.14,.4,'#a98c65');box(world,6.6,.7,3.8,.08,1.4,1.1,'#655643');box(world,7.5,.7,3.8,.08,1.4,1.1,'#655643');roomLabel('STAIRS',6.3,1.15,'#dce2cd');}
