 const cfg=floors[key];floorBase(cfg);if(key==='ground'){kitchen();rug(6.6,2.1,1.5,2.1,'#847861');}else if(key==='upstairs')bedrooms();else basement();addStairs();
 // The front threshold, with a welcome mat and a small sunlit window.
 box(world,0,.015,6.03,1.7,.04,.48,'#5d6550');box(world,0,.035,6.02,1.25,.025,.3,'#c7c28e');
 npcMeshes=[];clickTargets=[];for(const p of people.filter(p=>p.floor===key)){const ch=makeCharacter(p);ch.position.set(p.pos[0],0,p.pos[1]);world.add(ch);npcMeshes.push(ch);ch.traverse(o=>{if(o.isMesh&&o!==ch.userData.label)clickTargets.push(o);});}
 if(playerGroup)world.remove(playerGroup);playerGroup=makeCharacter({nick:'JORDAN “J”',color:'#bc795b',shirt:'#d79a4c',pants:'#47566c',hat:'#dec16d'},true);const start=key==='ground'?[0,4.35]:key==='upstairs'?[0,5]:[0,5];playerGroup.position.set(...[start[0],0,start[1]]);player=playerGroup;world.add(playerGroup);clickTargets.push(...getMeshes(playerGroup));
 lookAtPoint.set(0,0,0);camera.position.set(13,17,18);camera.lookAt(lookAtPoint);resize();$('#floor-title').textContent=cfg.title;$('#floor-eyebrow').textContent=`${key.toUpperCase()} FLOOR / 03`;$('#scene-room-label').textContent=cfg.rooms;document.querySelectorAll('.floor-btn').forEach(b=>b.classList.toggle('active',b.dataset.floor===key));renderPeople();}
