function animate(){requestAnimationFrame(animate);if(!renderer)return;const dt=Math.min(clock.getDelta(),.04);if(player){let dx=0,dz=0;if(keys.KeyW||keys.ArrowUp)dz-=1;if(keys.KeyS||keys.ArrowDown)dz+=1;if(keys.KeyA||keys.ArrowLeft)dx-=1;if(keys.KeyD||keys.ArrowRight)dx+=1;const speed=dt*3.1;if(dx||dz){const n=Math.hypot(dx,dz);player.position.x+=dx/n*speed;player.position.z+=dz/n*speed;state.walkTarget=null;player.rotation.y=Math.atan2(dx,dz);state.energy=Math.max(0,state.energy-dt*.24);}else if(state.walkTarget){const tx=state.walkTarget[0]-player.position.x,tz=state.walkTarget[1]-player.position.z,d=Math.hypot(tx,tz);if(d>.12){player.position.x+=tx/d*speed;player.position.z+=tz/d*speed;player.rotation.y=Math.atan2(tx,tz);}else{state.walkTarget=null;if(state.activePerson){openDialogue(state.activePerson);state.activePerson=null;}}}
 player.position.x=THREE.MathUtils.clamp(player.position.x,-7.2,7.2);player.position.z=THREE.MathUtils.clamp(player.position.z,-5.7,5.75);const bob=(keys.KeyW||keys.KeyS||keys.KeyA||keys.KeyD)?Math.sin(performance.now()*.012)*.035:0;player.children.forEach(c=>{if(c.geometry?.type==='BoxGeometry'&&c.position.y>.1)c.position.y+=bob*.08;});}
