function openDialogue(p){state.visited.add(p.id);$('#dialogue-name').textContent=p.name;$('#dialogue-role').textContent=`${p.tag} · ${floorName(p.floor)}`;$('#dialogue-mood').textContent=p.mood;$('#dialogue-line').textContent=p.line;$('#dialogue-relation').textContent=`✦ ${p.rep} / 100`;$('#dialogue-avatar').textContent=p.face;$('#dialogue-avatar').style.background=`linear-gradient(145deg,${p.color},${shade(p.color,-25)})`;
 const list=$('#choice-list');list.innerHTML=p.choices.map((c,i)=>`<button class="choice-btn" data-choice="${i}"><span class="choice-num">0${i+1}</span><span class="choice-copy"><b>${c[0]}</b><small>${c[1]}</small></span><span class="choice-effect ${c[3]==='bad'?'effect-bad':'effect-good'}">${c[2]}</span></button>`).join('');list.querySelectorAll('.choice-btn').forEach(btn=>btn.addEventListener('click',()=>choose(p,Number(btn.dataset.choice))));modal('#dialogue-modal');save();}
