import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const $ = (s) => document.querySelector(s);
const sceneRoot = $('#scene');

const people = [
  {id:'maya',name:'Maya Brooks',nick:'Maya',tag:'THE LISTENER',floor:'ground',pos:[-5.3,2.4],color:'#db9779',shirt:'#d4b14e',pants:'#38536b',hat:'#e0bd79',mood:'Thoughtful, a little homesick',line:'I keep thinking about my little sister. I want to be there for her, but I need to get steady first.',rep:50,face:'◡',choices:[['That sounds like a lot to carry. Want to tell me about her?','Listen without trying to fix it.','+ KINDNESS','good',5],['Maybe focus on today. One step at a time, right?','Offer a gentle reminder to stay present.','+ SUPPORT','good',3],['She’ll be fine without you. Don’t worry about it.','Brush off something important to her.','− TRUST','bad',-5]]},
  {id:'darnell',name:'Darnell Price',nick:'Darnell',tag:'THE PEACEMAKER',floor:'ground',pos:[3.7,1.3],color:'#8d624b',shirt:'#587f79',pants:'#4b4662',hat:'#cc734f',mood:'Upbeat, keeping the peace',line:'I’m trying to get everyone to sit down for dinner together. It’d be nice if we could feel like a team.',rep:50,face:'◡',choices:[['I’m in. Let’s see what we can make together.','Offer to help bring people around the table.','+ TEAMWORK','good',5],['That’s thoughtful. I can set out the plates.','Pitch in with a practical task.','+ KINDNESS','good',4],['Nobody wants to eat together. Save your breath.','Undercut community effort.','− TRUST','bad',-6]]},
  {id:'tasha',name:'Tasha Green',nick:'Tasha',tag:'THE BIG SISTER',floor:'ground',pos:[-1.6,-2.8],color:'#a86749',shirt:'#b969a1',pants:'#48516b',hat:'#ddb66a',mood:'Wary, but warm underneath',line:'The kitchen’s a little chaotic. I’m just trying to get breakfast sorted before everybody wakes up.',rep:50,face:'◡',choices:[['Want an extra pair of hands? I can help tidy up.','Offer to help with breakfast and cleanup.','+ HELPFUL','good',5],['I grabbed an extra snack. Would you like it?','Share a snack from your bag.','−1 SNACK · + CARE','food',7],['The mess is your problem, not mine.','Leave her to handle it alone.','− TRUST','bad',-5]]},
  {id:'leon',name:'Leon “L-Train” Carter',nick:'L-Train',tag:'THE MUSIC HEAD',floor:'upstairs',pos:[-5.2,-2.4],color:'#9b694f',shirt:'#4d79a2',pants:'#384460',hat:'#d26848',mood:'Quiet, focused on his music',line:'I’m putting together a beat in my head. Music helps me slow down when everything’s moving too fast.',rep:50,face:'◡',choices:[['What kind of sound are you going for?','Show genuine curiosity about his music.','+ CONNECTION','good',5],['Can you show me how you put a beat together?','Invite him to share something he loves.','+ ENCOURAGEMENT','good',4],['That’s just noise. Turn it off.','Dismiss his creative outlet.','− TRUST','bad',-6]]},
  {id:'nia',name:'Nia Williams',nick:'Nia',tag:'THE PLANNER',floor:'upstairs',pos:[4.8,-2.4],color:'#c88669',shirt:'#d57754',pants:'#416a62',hat:'#7d9dcb',mood:'Bright, always making a plan',line:'I’m writing down three little things I want to get done today. Nothing huge. Just things I can actually finish.',rep:50,face:'◡',choices:[['That’s a great idea. What’s one thing I could add?','Encourage achievable goals.','+ SUPPORT','good',5],['Want to take a walk later?','Offer friendly accountability.','+ FRIENDSHIP','good',5],['Three things? You should be doing way more.','Make her effort feel inadequate.','− TRUST','bad',-7]]},
  {id:'eddie',name:'Eddie Cole',nick:'Eddie',tag:'THE JOKESTER',floor:'upstairs',pos:[0,3.8],color:'#b37a55',shirt:'#607c4f',pants:'#44556a',hat:'#db8a53',mood:'Joking, covering a rough morning',line:'I had a weird dream I was late for a test I never studied for. Guess my brain’s got jokes.',rep:50,face:'◡',choices:[['That dream sounds stressful. How are you feeling now?','Notice the feeling underneath the joke.','+ EMPATHY','good',5],['I get those too. Brains are strange.','Share a little common ground.','+ CONNECTION','good',4],['You’re always making everything a joke. Grow up.','Turn a light moment into a put-down.','− TRUST','bad',-6]]},
  {id:'rosa',name:'Rosa Martinez',nick:'Rosa',tag:'THE GARDENER',floor:'basement',pos:[-4.6,-1.7],color:'#bd7959',shirt:'#79a678',pants:'#4a5065',hat:'#d7b97a',mood:'Calm, missing her garden',line:'I used to grow tomatoes with my abuela. There’s a sunny patch by the back steps that might work for a few pots.',rep:50,face:'◡',choices:[['Let’s find some pots. It could be a nice project.','Help her make a hopeful plan.','+ TEAMWORK','good',5],['Tell me about what you grew together.','Invite her to share a good memory.','+ CONNECTION','good',5],['Plants take too much work. Forget it.','Dismiss a source of joy.','− TRUST','bad',-5]]},
  {id:'coach',name:'Coach Al',nick:'Coach Al',tag:'THE MENTOR',floor:'basement',pos:[4.3,2.8],color:'#a56b51',shirt:'#cb7655',pants:'#4d627a',hat:'#dfbd66',mood:'Steady, giving folks room',line:'Nobody has to have it all figured out today. Showing up for the next right thing is plenty.',rep:50,face:'◡',choices:[['I needed to hear that. What helps you stay grounded?','Ask for a perspective to carry with you.','+ RESPECT','good',5],['I’m trying to find my rhythm here.','Share honestly where you are.','+ TRUST','good',4],['That sounds like something off a poster.','Mock sincere encouragement.','− TRUST','bad',-6]]},
  {id:'malik',name:'Malik Johnson',nick:'Malik',tag:'THE NIGHT OWL',floor:'basement',pos:[0,-3.3],color:'#8d5b44',shirt:'#b34d55',pants:'#434454',hat:'#cba365',mood:'Restless, trying to reset',line:'I was up late and missed breakfast. I’m trying to get my sleep back on track, but it’s a process.',rep:50,face:'◡',choices:[['Maybe we can figure out an easier morning routine.','Offer a practical, kind idea.','+ SUPPORT','good',5],['No rush. Some days getting up is the win.','Remind him patience matters.','+ KINDNESS','good',4],['Just stay up again tonight. It doesn’t matter.','Encourage a harder tomorrow.','− TRUST','bad',-7]]}
];

