const mats={};
function mat(c){return mats[c]||(mats[c]=new THREE.MeshStandardMaterial({color:c,roughness:.85,flatShading:true}));}
function box(p,x,y,z,w,h,d,c){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;p.add(m);return m;}
function cyl(p,x,y,z,rt,rb,h,c,n=7){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,n),mat(c));m.position.set(x,y,z);m.castShadow=true;p.add(m);return m;}
function sphere(p,x,y,z,r,c,n=8){const m=new THREE.Mesh(new THREE.SphereGeometry(r,n,6),mat(c));m.position.set(x,y,z);m.castShadow=true;p.add(m);return m;}

function setup(){renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(sceneRoot.clientWidth,sceneRoot.clientHeight);renderer.shadowMap.enabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;sceneRoot.appendChild(renderer.domElement);world=new THREE.Scene();world.background=new THREE.Color('#39463a');world.fog=new THREE.Fog('#39463a',24,42);camera=new THREE.OrthographicCamera(-10,10,7.4,-7.4,.1,100);camera.position.set(13,17,18);camera.lookAt(0,0,0);world.add(new THREE.HemisphereLight('#fff0d6','#627463',2.1));const sun=new THREE.DirectionalLight('#ffdfaa',3.2);sun.position.set(-7,13,7);sun.castShadow=true;world.add(sun);raycaster=new THREE.Raycaster();pointer=new THREE.Vector2();clock=new THREE.Clock();buildFloor(state.floor);bindUI();refreshUI();animate();window.addEventListener('resize',resize);}

function wall(x,z,w,d,h,c){box(world,x,h/2,z,w,h,d,c)}
function roomLabel(text,x,z){const c=document.createElement('canvas');c.width=512;c.height=100;const ctx=c.getContext('2d');ctx.fillStyle='#19211bcc';ctx.beginPath();ctx.roundRect(0,0,512,100,14);ctx.fill();ctx.strokeStyle='#e3d4b166';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#eee5cf';ctx.font='500 30px monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text.toUpperCase(),256,52);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const m=new THREE.Mesh(new THREE.PlaneGeometry(3.2,.62),new THREE.MeshBasicMaterial({map:tex,transparent:true,side:THREE.DoubleSide,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(x,.04,z);world.add(m)}
function floorBase(cfg){box(world,0,-.17,0,17,.32,13,cfg.floor);box(world,0,-.335,0,17.4,.08,13.4,'#463f34');for(let z=-5.4;z<=5.4;z+=1.15)box(world,0,-.004,z,16.9,.015,.025,'#ffffff10');wall(0,6.35,17,.28,1.5,cfg.wall);wall(-8.35,0,.3,12.7,1.5,cfg.wall);wall(8.35,0,.3,12.7,1.5,cfg.wall);wall(-4.5,-6.35,7.5,.28,1.5,cfg.wall);wall(4.5,-6.35,7.5,.28,1.5,cfg.wall)}
function rug(x,z,w,d,c){box(world,x,0,z,w,.035,d,c);box(world,x,.02,z,w-.3,.018,d-.3,c==='#b66b4d'?'#d19069':'#9eaf92')}
function plant(x,z){cyl(world,x,.27,z,.2,.24,.52,'#9b6845',6);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;sphere(world,x+Math.cos(a)*.23,.86,z+Math.sin(a)*.23,.18,'#718b5b',6)}}
