 function openDialogue(p){state.activePerson=p.id;$('#dialogue-avatar').style.background=`linear-gradient(145deg,${p.color},${p.shirt})`;$('#dialogue-avatar').textContent=p.face;$('#dialogue-name').textContent=p.name;$('#dialogue-role').textContent=`${p.tag} · ${p.floor==='ground'?'GROUND FLOOR':p.floor==='upstairs'?'UPSTAIRS':'BASEMENT'}`;$('#dialogue-mood').textContent=p.mood;$('#dialogue-line').textContent=p.line;$('#dialogue-relation').textContent=`✦ ${p.rep}`;const list=$('#choice-list');list.innerHTML='';p.choices.forEach((c,i)=>{const b=document.createElement('button');b.className='choice-item';b.innerHTML=`<span class="choice-letter">${String.fromCharCode(65+i)}</span><span><b>${c[0]}</b><small>${c[1]}</small></span><em class="${c[3]}">${c[2]}</em>`;b.onclick=()=>choose(p,c,b);list.appendChild(b)});openModal('dialogue-modal')}
